package com.myeshopping.invoiceservice.controller;
import com.myeshopping.invoiceservice.dto.*; import com.myeshopping.invoiceservice.entity.Invoice; import com.myeshopping.invoiceservice.service.InvoiceService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.UUID;
@RestController @RequestMapping("/api/v1/invoices") @RequiredArgsConstructor public class InvoiceController { private final InvoiceService service; @PostMapping public ResponseEntity<ApiResponse<Invoice>> generate(@Valid @RequestBody InvoiceRequest request){return ok("Invoice generated successfully",service.generate(request));} @GetMapping("/{id}") public ResponseEntity<ApiResponse<Invoice>> get(@PathVariable Long id){return ok("Invoice fetched successfully",service.get(id));} @GetMapping("/order/{orderId}") public ResponseEntity<ApiResponse<Invoice>> order(@PathVariable Long orderId){return ok("Invoice fetched successfully",service.getByOrder(orderId));} private <T> ResponseEntity<ApiResponse<T>> ok(String message,T data){return ResponseEntity.ok(ApiResponse.<T>builder().success(true).message(message).data(data).timestamp(Instant.now()).correlationId(UUID.randomUUID()).build());} }
